#include "Std_Types.h"         /* AUTOSAR standard types */

/*==================[type definitions]=======================================*/
typedef uint32 TS_CacheStatusType;

/*==================[macros]=================================================*/

/*------------------[TS_CacheDisable]-----------------------------------------*/

#if (defined TS_CacheDisable) /* guard to prevent double definition */
#error "TS_CacheDisable already defined"
#endif /* if (defined TS_CacheDisable) */

/** \brief Disables data and instruction cache and returns previous state.
 **
 ** This macro disables all caches by clearing the enable flag in the system
 ** control register. The previous status of the enable flags is returned.
 **
 ** ATTENTION: This function may be called within MCAL code, but this call
 **            must be in a critical section (i.e. a section surrounded by the
 **            Schedule Manager functions SchM_Enter_xxx() and SchM_Exit_xxx()).
 **/

#if ( defined(_GREENHILLS_C_S6J3_) )

#if (defined EB_STATIC_CHECK)
#define TS_CacheDisable()       0
#else
#define TS_CacheDisable()       TS_CacheDisableAsm()
#endif

TS_CacheStatusType TS_CacheDisableAsm(void);

#else
//#error "Unsupported compiler for the architecture!"
#endif

/*------------------[TS_CacheRestore]-----------------------------------------*/

#if (defined TS_CacheRestore) /* guard to prevent double definition */
#error "TS_CacheRestore already defined"
#endif /* if (defined TS_CacheRestore) */

/** \brief Restores cache enable state
 **
 ** This macro restores the cache enable state to the state
 ** defined by the parameter. This should be the value as 
 ** returned by the previous call to TS_CacheDisable().
 **
 ** ATTENTION: This function may be called within MCAL code, but this call
 **            must be in a critical section (i.e. a section surrounded by the
 **            Schedule Manager functions SchM_Enter_xxx() and SchM_Exit_xxx()).
 **/
#if ( defined(_GREENHILLS_C_S6J3_) )

#if (defined EB_STATIC_CHECK)
#define TS_CacheRestore(s)        
#else
#define TS_CacheRestore(s)      TS_CacheRestoreAsm(s) /* MISRA-1 */ /* PRQA S 3453 */ /* macros used like functions. */
#endif

void TS_CacheRestoreAsm(TS_CacheStatusType CacheStatus);

#else
//#error "Unsupported compiler for the architecture!"
#endif

#endif /* ifndef TS_ATOMIC_LIB_ARCH_H */
